(()=>{'use strict';
const C=window.LessonCore,D=window.LessonContent,Sim=window.AppSim,$=s=>document.querySelector(s),esc=C.escape;
let simulation=Sim.initial(),simTicker=null,lastDemoLabel=null,lastSimAction='',motionRequested=false;
let state=C.initial(),selected=null,drag=null,undo=[],demoResult=null,noticeLine='',storageError=false,toastTimer;
try{const raw=localStorage.getItem(C.KEY);if(raw){const old=JSON.parse(raw);if(old.version===1)localStorage.setItem(C.KEY+'-previous',raw);state=C.restore(old);}}catch{storageError=true;}
const teacher=new URLSearchParams(location.search).get('teacher')==='1';
const tr=(en,zh)=>esc(en)+(state.lang==='bi'&&zh?`<span class="zh" lang="zh-Hans">${esc(zh)}</span>`:'');
const pair=v=>tr(v[0],v[1]);
const btn=(en,zh,act,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-act="${act}" ${extra}>${tr(en,zh)}</button>`;
const art=(id,cls='')=>`<img class="${cls}" src="assets/playground/${id}-art.svg" alt="${esc(D.demos.find(d=>d.id===id)?.kind[0]||'App illustration')}">`;
function get(path){return path.split('.').reduce((v,k)=>v?.[k],state)??'';}
function set(path,value){let o=state;const ks=path.split('.');for(const k of ks.slice(0,-1))o=o[k];o[ks.at(-1)]=value;}
const field=(en,zh,path,hint='',placeholder='')=>`<label class="field">${tr(en,zh)}<input type="text" data-bind="${path}" value="${esc(get(path))}" maxlength="${path==='student.name'?90:350}" placeholder="${esc(placeholder)}">${hint?`<small>${hint}</small>`:''}</label>`;
function save(){state.updated=new Date().toISOString();try{localStorage.setItem(C.KEY,JSON.stringify(state));storageError=false;}catch{storageError=true;}const el=$('#save-status');if(el)el.textContent=state.lang==='bi'?(storageError?'尚未保存，请下载备份':'已保存在此浏览器'):(storageError?'Not saved · download a backup':'Saved in this browser');}
function toast(en,zh){const el=$('#toast');el.textContent=state.lang==='bi'?en+' / '+zh:en;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,5000);}
function language(){return `<select id="language" aria-label="Language / 语言"><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="bi" ${state.lang==='bi'?'selected':''}>English + 中文</option></select>`;}
function brand(){return `<button class="brand" data-act="home" aria-label="Lesson home"><b>↗</b><span>CS with Mr Dave<small>YEAR 9 · APP PLAYGROUND</small></span></button>`;}
function landing(){return `<header class="topbar">${brand()}<div class="toolbar">${language()}${btn('Words','词汇','glossary','quiet')}</div></header><main class="landing" id="main"><section class="hero"><div><p class="eyebrow">60 minutes · Imagine → Sketch → Start</p><h1>${tr('What would','你想')}<br><em>${tr('you create?','创造什么？')}</em></h1><p class="lead">${tr('An app for your style, your interests, your world. Try some ideas. Then invent your own homepage.','为你的风格、兴趣和世界设计应用。先试试一些创意，再创造自己的主页。')}</p><div class="hero-tags"><span>${tr('See it','看一看')}</span><span>${tr('Tap it','点一点')}</span><span>${tr('Sketch it','画出来')}</span></div><p>${tr('Start with a sketch. Open MIT afterwards, with your own idea ready.','先画草图。有了自己的想法后，再打开 MIT。')}</p></div><div class="hero-phones" aria-label="Three different fictional app designs">${['gaming','fashion','weather'].map(id=>`<img src="assets/playground/${id}-phone.svg" alt="${esc(D.demos.find(d=>d.id===id).kind[0])} example">`).join('')}</div></section><section class="entry card"><h2>${tr('Enter your design studio','进入你的设计工作室')}</h2><form id="entry-form"><div class="entry-grid">${field('Your name','姓名','student.name')}${field('Class / form','班级','student.form')}</div><label class="check"><input id="entry-guided" type="checkbox" ${state.guided?'checked':''}>${tr('Show extra hints and phrase starters','显示更多提示和短语开头')}</label><div class="row"><button type="submit" class="btn primary">${tr(state.joined?'Continue my design':'Let’s create',state.joined?'继续我的设计':'开始创作')} →</button>${state.joined?btn('Start a new response','开始新答卷','new','quiet'):''}<span class="small">${tr('Short phrases and Mandarin notes welcome.','可以用短语或中文笔记。')}</span></div></form></section><div class="landing-goals"><strong>WAGBA</strong><p>${pair(D.wagba)}</p><div class="three">${['K','S','U'].map(k=>`<article><b>${pair(D.areas[k])}</b><p>${pair(D.goals[k])}</p></article>`).join('')}</div></div><p class="small muted">${tr('This is a design lesson. A mock-up shows your idea; the controls will be programmed in a later practical.','本课先做设计。模型展示你的想法；之后的实践课再为控件编程。')}</p></main>`;}
function current(){return C.pages.find(p=>p.id===state.slide)||C.pages[0];}
function rail(){const p=current();return `<aside class="rail" id="goals"><strong class="eyebrow">WAGBA</strong><p>${pair(D.wagba)}</p>${['K','S','U'].map(k=>`<div class="rail-goal"><strong>${pair(D.areas[k])}</strong><p>${pair(D.goals[k])}</p></div>`).join('')}<nav aria-label="Activity stages">${C.stages.map((g,i)=>{const first=C.pages.find(p=>p.group===g[0]);const open=C.canVisit(state,first.id,teacher);return `<button class="stage-link ${p.group===g[0]?'active':''}" data-jump="${first.id}" ${open?'':'disabled'} ${p.group===g[0]?'aria-current="step"':''}><span>${open?i+1:'🔒'}</span>${tr(g[1],g[2])}</button>`;}).join('')}</nav><p class="small muted">${tr('Forward, one slide at a time. Revisit any unlocked stage.','逐页向前学习。可以回看已解锁的阶段。')}</p></aside>`;}
function shell(){const p=current(),group=C.stages.find(g=>g[0]===p.group),local=C.pages.filter(x=>x.group===p.group),n=local.findIndex(x=>x.id===p.id),i=C.pages.indexOf(p);return `<header class="topbar">${brand()}<div class="toolbar">${language()}${btn('Words','词汇','glossary','quiet small')}${btn('MIT guides','MIT 指南','guides','quiet small')}${btn('Save','保存','save-menu','quiet small')}${btn(state.student.name,'个人信息','identity','quiet small')}</div></header><div class="layout" id="layout">${rail()}<main class="main" id="main"><button class="mobile-goals btn quiet small" data-act="goals">${tr('WAGBA & activities','目标与活动')} ☰</button><div class="slide-meta"><span>${tr(group[1],group[2])}</span><span>${n+1} / ${local.length} · ${group[3]} ${tr('min for this activity','分钟 / 本活动')}</span></div><div class="dots" aria-label="Activity slides">${local.map((x,j)=>`<button data-jump="${x.id}" class="${j===n?'current':''} ${state.visited.includes(x.id)?'visited':''}" ${C.canVisit(state,x.id,teacher)?'':'disabled'} aria-label="${esc(x.en)}" ${j===n?'aria-current="step"':''}></button>`).join('')}</div><section class="slide"><h1 tabindex="-1" id="slide-title">${tr(p.en,p.zh)}</h1>${state.migrated&&p.id==='read-welcome'?`<div class="note">${tr('Your earlier design is safe. This new route starts with the app playground.','之前的设计已保留。新版从应用创意乐园开始。')}</div>`:''}${slideBody(p.id)}</section>${noticeLine?`<div class="feedback reminder" role="status">${noticeLine}</div>`:''}<footer class="slide-nav"><div>${i?btn('Back','上一页','back','quiet'):btn('Home','首页','home','quiet')}</div><span id="save-status" class="small muted">${tr(storageError?'Not saved · download a backup':'Saved in this browser',storageError?'尚未保存，请下载备份':'已保存在此浏览器')}</span>${i<C.pages.length-1?btn(nextLabel(),'下一步','next','primary'):btn('Save my PDF','保存 PDF','pdf','primary')}</footer>${teacher?teacherNotes():''}</main></div>`;}
function nextLabel(){return ({gallery:'Try this app →',play:'Spot the design clues →',topic:'Create my own app →',sketch:'Plan my first tap →','try-home':'Start my project in MIT →','setup-5':'Keep creating →',showcase:'Save my design →'})[state.slide]||'Next slide →';}
function info(en,zh){return `<p class="instruction">${tr(en,zh)}</p>`;}
function demoButtonText(d,i){if(i===1&&['fashion','camera'].includes(d.id)&&simulation.saved[d.id])return [d.id==='fashion'?'Saved ♥':'Saved ★','已收藏'];if(d.id==='planner'&&i===0){const t=simulation.timer;return t.running?['Pause timer','暂停计时']:t.phase==='finished'?['Restart timer','重新计时']:t.phase==='paused'?['Resume timer','继续计时']:d.buttons[i];}return d.buttons[i];}
function demo(id=state.demo,interactive=true){const d=D.demos.find(d=>d.id===id)||D.demos[0],active=interactive&&id===state.demo&&demoResult!==null;return `<div class="phone-demo" style="--phone-accent:${d.accent};--phone-bg:${d.bg}"><div class="phone-speaker"></div><div class="phone-page"><div class="app-kicker">${pair(d.kind)}</div><h2>${pair(d.title)}</h2><p>${pair(d.tag)}</p><div class="demo-media">${active?simulationScene(d,true):art(d.id,'demo-art')}</div><div class="demo-controls">${d.buttons.map((b,i)=>`<button data-demo-tap="${i}" ${interactive?'':'disabled'} ${i===1&&['fashion','camera'].includes(d.id)?`aria-pressed="${!!simulation.saved[d.id]}"`:''} class="${i===0?'solid':''}">${pair(interactive?demoButtonText(d,i):b)}</button>`).join('')}</div><small>${tr('Fictional app · sample data','虚构应用 · 示例数据')}</small></div></div>`;}
function reaction(icon,active,compact,id){return `<div class="sim-favourite ${compact?'compact':''}" data-motion>${art(id,'favourite-art')}<div class="reaction-cluster ${active?'is-saved':''}" aria-hidden="true"><span class="reaction-main ${icon==='heart'?'heart-mark':'star-mark'}">${icon==='heart'?(active?'♥':'♡'):(active?'★':'☆')}</span>${active?`<span class="reaction-particle p1">${icon==='heart'?'♥':'✦'}</span><span class="reaction-particle p2">${icon==='heart'?'♥':'✦'}</span><span class="reaction-particle p3">${icon==='heart'?'♥':'✧'}</span>`:''}</div><span class="saved-indicator">${active?tr('Saved','已收藏'):tr('Not saved','未收藏')}</span></div>`;}
function simulationScene(d,compact=false){const mode=Sim.mode(d.id,demoResult),cls=compact?' compact':'';let html='';
 if(mode==='heart'||mode==='star')return reaction(mode,simulation.saved[d.id],compact,d.id);
 if(mode==='catalogue')html=`<div class="scene-heading">${tr('Outfit gallery','穿搭画廊')}</div><div class="sim-card-grid">${[['Everyday','日常'],['After school','课后']].map((v,i)=>`<article class="sim-product ${i?'alternate':''}">${art('fashion')}<b>${tr(v[0],v[1])}</b></article>`).join('')}</div>`;
 if(mode==='details')html=`<div class="scene-heading">${tr(d.id==='gaming'?'Controller details':'Camera details',d.id==='gaming'?'控制器介绍':'相机介绍')}</div><div class="sim-details">${art(d.id)}<div class="feature-chips"><span>${tr(d.id==='gaming'?'Button layout':'Sample photos',d.id==='gaming'?'按钮布局':'样片')}</span><span>${tr(d.id==='gaming'?'Colour choices':'Key features',d.id==='gaming'?'颜色选项':'主要功能')}</span></div></div>`;
 if(mode==='compare')html=`<div class="scene-heading">${tr('Compare controllers','比较控制器')}</div><div class="sim-card-grid">${[['A','Small grip','小握柄'],['B','Wide grip','宽握柄']].map((v,i)=>`<article class="sim-product ${i?'alternate':''}">${art('gaming')}<b>${v[0]}</b><small>${tr(v[1],v[2])}</small></article>`).join('')}</div>`;
 if(mode==='weather'){const c=Sim.cities[simulation.city];html=`<div class="scene-heading">${esc(simulation.city)}</div><div class="sim-weather"><div class="weather-picture">${art('weather')}${c.sky.toLowerCase().includes('rain')?'<div class="rain-cue" aria-hidden="true"><i></i><i></i><i></i><i></i></div>':''}</div><strong>${c.temp}°C</strong><span>${tr(...c.sky.split(' / '))}</span></div>`;}
 if(mode==='city')html=`<div class="scene-heading">${tr('Choose a sample city','选择示例城市')}</div><div class="sim-city-options">${Object.keys(Sim.cities).map(city=>compact?`<button data-sim-action="city" data-sim-value="${esc(city)}" aria-pressed="${simulation.city===city}" class="${simulation.city===city?'is-picked':''}">${esc(city)}</button>`:`<span class="${simulation.city===city?'is-picked':''}">${esc(city)}</span>`).join('')}</div><div class="selected-city">${esc(simulation.city)} <b>${Sim.cities[simulation.city].temp}°C</b></div>`;
 if(mode==='events')html=`<div class="scene-heading">${tr('Explore sample events','浏览示例活动')}</div><div class="event-list">${[['◉','Film afternoon','电影下午场'],['✦','Art exhibition','艺术展览'],['↗','Sports session','运动活动']].map(v=>`<div><span aria-hidden="true">${v[0]}</span><b>${tr(v[1],v[2])}</b></div>`).join('')}</div>`;
 if(mode==='slots')html=`<div class="scene-heading">${tr('Choose a sample time','选择示例时间')}</div><div class="sim-slots">${Sim.slots.map(slot=>compact?`<button data-sim-action="slot" data-sim-value="${slot}" aria-pressed="${simulation.slot===slot}" class="${simulation.slot===slot?'is-picked':''}">${slot}</button>`:`<span class="${simulation.slot===slot?'is-picked':''}">${slot}</span>`).join('')}</div><div class="slot-result" aria-live="polite">${simulation.slot?`<b class="selection-tick" aria-hidden="true">✓</b> ${esc(simulation.slot)} · ${tr('Selected','已选择')}`:tr('Tap a time on the phone','在手机上选择时间')}</div><small>${tr('Simulation only · no booking is made','仅为模拟 · 不会真的预约')}</small>`;
 if(mode==='timer'){const t=simulation.timer;html=`<div class="scene-heading">${tr('10-second sample timer','十秒示例计时器')}</div><div class="timer-dial" data-timer-progress style="--timer-fill:${(10-t.remaining)*10}%"><span role="timer" aria-live="off" data-timer-digits>00:${String(t.remaining).padStart(2,'0')}</span></div><div class="timer-state" data-timer-state role="status">${timerStateText()}</div>${compact?`<button class="sim-reset" data-sim-action="reset">${tr('Reset sample','重置示例')}</button>`:''}`;}
 if(mode==='timetable')html=`<div class="scene-heading">${tr('Sample timetable','示例时间表')}</div><div class="sim-timetable">${[['09:00','Design','设计'],['10:00','Maths','数学'],['12:00','Lunch','午餐']].map((v,i)=>`<div class="${i?'':'current-lesson'}"><b>${v[0]}</b><span>${tr(v[1],v[2])}</span>${i?'':`<small>${tr('Now','现在')}</small>`}</div>`).join('')}</div>`;
 return `<div class="sim-scene scene-${mode}${cls}" data-motion>${html}</div>`;
}
function timerStateText(){const phases={ready:['Ready','就绪'],running:['Running','计时中'],paused:['Paused','已暂停'],finished:['Finished','计时结束']};return (phases[simulation.timer.phase]||phases.ready)[state.lang==='bi'?1:0];}
function responseText(d){if(d.id==='weather'&&demoResult===0){const c=Sim.cities[simulation.city],sky=c.sky.split(' / ');return ['Sample forecast for '+simulation.city+': '+c.temp+'°C, '+sky[0].toLowerCase()+'.',simulation.city+' 的示例天气：'+c.temp+'°C，'+sky[1]+'。'];}if(lastSimAction==='city'&&d.id==='weather')return ['The sample forecast changes to '+simulation.city+': '+Sim.cities[simulation.city].temp+'°C.','示例天气已切换为 '+simulation.city+'：'+Sim.cities[simulation.city].temp+'°C。'];if(lastSimAction==='slot'&&d.id==='booking')return ['You selected '+simulation.slot+' in this simulation. No booking is made.','你在模拟中选择了 '+simulation.slot+'。不会真的预约。'];if(demoResult===1&&['fashion','camera'].includes(d.id)){const on=simulation.saved[d.id];return on?d.responses[1]:d.id==='fashion'?['The heart is removed. This look is no longer saved.','爱心移除，这套造型不再收藏。']:['The star is removed. This camera is no longer saved.','星标移除，这台相机不再收藏。'];}if(d.id==='planner'&&demoResult===0)return ['The sample timer can run, pause and restart. Watch the number and progress ring.','示例计时器可以开始、暂停和重新计时。观察数字和进度环。'];return d.responses[demoResult];}
function demoFeedback(){const d=D.demos.find(d=>d.id===state.demo);if(demoResult===null)return `<div class="tap-hint"><span>↖</span><h3>${tr('Try a control on the phone','试着点击手机上的控件')}</h3><p>${tr('Tap a button. Watch the app’s response appear here.','点击按钮，应用的回应会显示在这里。')}</p></div>`;return `<div class="demo-response"><div class="event-caption" aria-live="polite"><span class="eyebrow">${tr('The user taps','用户点击')}</span><h3>${pair(lastDemoLabel||d.buttons[demoResult])}</h3></div><span class="response-arrow" aria-hidden="true">↓</span><div class="response-screen">${simulationScene(d)}<p class="simulation-caption" aria-live="polite">${pair(responseText(d))}</p></div><div class="mini-vocab"><b>${tr('Event','事件')}</b> ${tr('the tap','点击')} → <b>${tr('Response','回应')}</b> ${tr('what changes','发生的变化')}</div></div>`;}
function stopSimTicker(pause=false){clearInterval(simTicker);simTicker=null;if(pause){const active=simulation.timer.running;Sim.advance(simulation);simulation.timer.running=false;simulation.timer.deadline=0;if(active&&simulation.timer.remaining>0)simulation.timer.phase='paused';}}
function updateTimerUI(){Sim.advance(simulation);const t=simulation.timer;document.querySelectorAll('[data-timer-digits]').forEach(el=>el.textContent='00:'+String(t.remaining).padStart(2,'0'));document.querySelectorAll('[data-timer-progress]').forEach(el=>el.style.setProperty('--timer-fill',((10-t.remaining)*10)+'%'));document.querySelectorAll('[data-timer-state]').forEach(el=>{const text=timerStateText();if(el.textContent!==text)el.textContent=text;});if(!t.running){clearInterval(simTicker);simTicker=null;if(state.demo==='planner'&&demoResult===0){const d=D.demos.find(d=>d.id==='planner'),b=document.querySelector('[data-demo-tap="0"]');if(b)b.innerHTML=pair(demoButtonText(d,0));}}}
function refreshSimTicker(){stopSimTicker();if(['read-tap','play'].includes(state.slide)&&state.demo==='planner'&&demoResult===0&&simulation.timer.running){updateTimerUI();simTicker=setInterval(updateTimerUI,200);}}
function plannedCue(effect){if(!effect||effect==='other')return '<span class="prototype-custom" aria-hidden="true">↗</span>';return effect==='save'?'<span class="prototype-heart" aria-hidden="true">♥</span>':effect==='timer'?'<span class="prototype-clock" aria-hidden="true">◷</span>':effect==='play'?'<span class="prototype-play" aria-hidden="true">▶</span>':effect==='choose'?'<span class="prototype-options" aria-hidden="true"><i></i><i></i><i></i></span>':'<span class="prototype-page" aria-hidden="true"><i></i><i></i><i></i></span>';}
function cueNewElement(){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const el=[...document.querySelectorAll('[data-node]')].find(el=>el.dataset.node===selected);if(el&&typeof el.animate==='function')el.animate([{opacity:.3,transform:'scale(.94)'},{opacity:1,transform:'scale(1)'}],{duration:240,easing:'ease-out'});}
function slideBody(id){
 if(id==='read-welcome')return `${info('Today, be the app designer. Make ONE homepage (the first screen) about something you care about.','今天当应用设计师，为你关心的主题设计一个主页，也就是第一个界面。')}<div class="outcome-visual"><img src="assets/playground/camera-phone.svg" alt="Camera catalogue homepage example"><div><span class="big-label">01</span><h2>${tr('Your topic. Your look.','你的主题，你的风格。')}</h2><p>${tr('A name or logo, some useful content, and two things a user can tap.','应用名称或标志、有用的内容，以及两个可以点击的项目。')}</p><div class="outcome-route"><b>${tr('Explore','探索')}</b><span>→</span><b>${tr('Sketch','画草图')}</b><span>→</span><b>${tr('Start MIT','开始 MIT')}</b></div></div></div>`;
 if(id==='read-tap')return `${info('Try the two buttons. What changes after each tap?','试试两个按钮。每次点击后有什么变化？')}<div class="demo-stage">${demo()}${demoFeedback()}</div>`;
 if(id.startsWith('quiz-'))return quiz(Number(id.slice(-1)));
 if(id.startsWith('learn-'))return learning(id.slice(6));
 if(id==='gallery')return `${info('Which idea catches your eye? Select a mock-up to try. Your own app can be completely different.','哪个创意吸引你？选择一个模型试试。你自己的应用可以完全不同。')}<div class="gallery">${D.demos.map(d=>`<button class="gallery-card ${state.demo===d.id?'chosen':''}" data-demo="${d.id}" aria-pressed="${state.demo===d.id}"><img src="assets/playground/${d.id}-phone.svg" alt="${esc(d.kind[0])} homepage mock-up"><span class="gallery-caption"><strong>${pair(d.kind)}</strong><span>${pair(d.tag)}</span><b>${state.demo===d.id?tr('Selected ✓','已选择 ✓'):tr('Choose to try','选择并体验')} ↗</b></span></button>`).join('')}</div>`;
 if(id==='play')return `${info('Try both controls in this example. Notice what the app does after each tap.','试试这个例子的两个控件。注意每次点击后应用做什么。')}<div class="demo-pills">${D.demos.map(d=>`<button data-demo="${d.id}" class="${state.demo===d.id?'chosen':''}">${pair(d.kind)}</button>`).join('')}</div><div class="demo-stage">${demo()}${demoFeedback()}</div>`;
 if(id==='anatomy')return `${info('Look at how the parts work together. A first homepage can be simple and still feel like your own app.','观察各部分如何配合。第一版主页可以很简单，同时有你自己的风格。')}<div class="anatomy"><div class="annotated-phone">${demo('camera',false)}<span class="callout call-title">${tr('Identity','应用身份')}</span><span class="callout call-picture">${tr('Content','内容')}</span><span class="callout call-button">${tr('Clear controls','清楚的控件')}</span></div><div class="design-clues"><article><b>01</b><h3>${tr('A name or logo','名称或标志')}</h3><p>${tr('It helps people recognise which app they opened.','帮助用户辨认自己打开了什么应用。')}</p></article><article><b>02</b><h3>${tr('Pictures and useful content','图片与有用的内容')}</h3><p>${tr('Show what your app is about. Start with one thing people will enjoy or use.','让用户看出应用主题。先展示一项他们会喜欢或用得上的内容。')}</p></article><article><b>03</b><h3>${tr('Controls with clear labels','标签清楚的控件')}</h3><p>${tr('Say what each tap will do. Leave space around buttons so people can find and tap them.','说明每次点击会做什么。在按钮周围留空，方便找到和点击。')}</p></article></div></div>`;
 if(id==='notice')return `${info('A homepage needs to help a person know where to tap. Which button label makes its job clearer?','主页需要让用户知道该点哪里。哪个按钮标签更清楚？')}<div class="anatomy"><div class="annotated-phone">${demo('camera',false)}<span class="callout call-title">${tr('Name / identity','名称 / 身份')}</span><span class="callout call-picture">${tr('Content / picture','内容 / 图片')}</span><span class="callout call-button">${tr('A clear tap target','清楚的点击项目')}</span></div><div class="label-choice">${[['go','Go','开始'],['detail','View camera details','查看相机介绍']].map(([v,en,zh])=>`<button data-notice="${v}" class="choice ${state.notice===v?'chosen':''}">${tr(en,zh)}</button>`).join('')}${state.notice?`<div class="feedback">${tr(state.notice==='detail'?'“View camera details” tells the user what will open. Use labels that fit YOUR app.':'“Go” is short, but it does not say where. A specific label helps the user predict the result.',state.notice==='detail'?'“查看相机介绍”让用户知道会打开什么。为你自己的应用使用合适的标签。':'“开始”很短，但没有说明去哪里。具体的标签能帮助用户预期结果。')}</div>`:''}</div></div>`;
 if(id==='topic')return `${info('What would YOU like an app to be about? Choose a starting idea or type your own.','你希望自己的应用是什么主题？选一个起点，或写出自己的想法。')}<div class="topic-grid">${D.topics.map((t,i)=>`<button data-topic="${i}" class="choice ${state.design.topic===t[state.lang==='bi'?1:0]?'chosen':''}">${pair(t)}</button>`).join('')}</div>${field('My app’s topic','我的应用主题','design.topic',tr('An interest, hobby, product, story or useful tool. You decide.','兴趣、爱好、产品、故事或实用工具，由你决定。'),'e.g. my comic characters / 例如：我的漫画角色')}<div class="note">${tr('Choose any school-appropriate topic. Keep one small idea for your first homepage.','可以选择任何适合学校的主题。为第一个主页选一个小创意即可。')}</div>`;
 if(id==='name')return `${info('You are now creating your own app. Give it a name you would enjoy seeing on a phone.','现在开始创作你自己的应用。起一个你想在手机上看到的名字。')}<div class="project-chip">${tr('Your topic','你的主题')}: ${esc(state.design.topic)}</div>${field('My app’s name','我的应用名称','design.title',tr('A short name is enough. You can change it later.','简短名称就可以，之后还能修改。'))}<div class="name-preview"><span>${esc(state.design.logo)}</span><strong id="live-app-name">${esc(state.design.title)||tr('Your app name','你的应用名称')}</strong></div>`;
 if(id==='purpose')return `${info('What is the FIRST thing your app will let someone do? Start with one feature.','你的应用首先让用户做什么？先专注一个功能。')}<div class="phrase-choices">${[['Browse a collection','浏览收藏'],['Find information','查找资料'],['Choose a story','选择故事'],['Use a timer','使用计时器'],['See a timetable','查看时间表'],['Explore my idea','探索我的创意']].map(t=>`<button data-phrase="${esc(t[state.lang==='bi'?1:0])}" data-target="design.feature">${pair(t)}</button>`).join('')}</div>${field('My app lets someone…','我的应用让用户可以……','design.feature',tr('Select a starter above, then change it to fit your own idea.','可以先选上面的短语，再改成自己的想法。'))}`;
 if(id==='audience')return `${info('Imagine one kind of person opening your app. Who would enjoy it or find it useful?','想象一类会打开你的应用的人。谁会喜欢它，或觉得它有用？')}<div class="audience-pictures"><span>🎮</span><span>📷</span><span>🎨</span><span>🏀</span></div><div class="phrase-choices">${[['People who share my hobby','和我有相同爱好的人'],['Students in my school','我们学校的学生'],['People choosing a product','挑选产品的人'],['People who enjoy stories','喜欢故事的人']].map(t=>`<button data-phrase="${esc(t[state.lang==='bi'?1:0])}" data-target="design.audience">${pair(t)}</button>`).join('')}</div>${field('My app is for…','我的应用为……设计','design.audience',tr('A group of people is enough. No long explanation.','写出一类人即可，不用长篇解释。'))}`;
 if(id==='brand')return `${info('Choose a simple logo symbol and colour mood for your homepage. You can draw your own logo on paper instead.','为主页选择一个简单的标志符号和配色。也可以在纸上画自己的标志。')}<div class="brand-lab"><div class="brand-preview theme-${state.design.theme}"><span>${esc(state.design.logo)}</span><h2>${esc(state.design.title)}</h2></div><div><h3>${tr('Logo symbol','标志符号')}</h3><div class="symbol-grid">${['✦','★','◉','⚡','♥','♫','◆','☁','☀','✿','➜','●'].map(x=>`<button data-logo="${x}" class="${state.design.logo===x?'chosen':''}" aria-label="Logo ${x}">${x}</button>`).join('')}</div><h3>${tr('Colour mood','配色')}</h3><div class="swatches">${[['mint','Mint','薄荷绿'],['lilac','Lilac','浅紫'],['peach','Peach','桃色'],['sky','Sky','天空蓝'],['night','Night','深色']].map(([v,en,zh])=>`<button data-theme="${v}" class="theme-${v} ${state.design.theme===v?'chosen':''}" aria-pressed="${state.design.theme===v}">${tr(en,zh)}</button>`).join('')}</div></div></div>`;
 if(id==='method')return `${info('How would you like to sketch your homepage? Both choices are equally good.','你想怎样画主页草图？两种方式都可以。')}<div class="method-grid">${[['paper','✎','Draw on paper','画在纸上','Collect a sheet from the front, or ask your teacher. Draw a phone outline and your homepage inside it.','到教室前方拿纸，或向老师索取。先画手机轮廓，再在里面画主页。'],['digital','▣','Use the digital sketch board','使用数字草图板','Add and move text, pictures and buttons here. You can edit every label.','在这里添加和移动文字、图片、按钮。每个标签都可以修改。']].map(([v,icon,en,zh,t,z])=>`<button class="method-card ${state.design.method===v?'chosen':''}" data-method="${v}" aria-pressed="${state.design.method===v}"><span class="method-icon">${icon}</span><h2>${tr(en,zh)}</h2><p>${tr(t,z)}</p><b>${state.design.method===v?tr('My choice ✓','我的选择 ✓'):tr('Choose this','选择这个')} →</b></button>`).join('')}</div>`;
 if(id==='sketch')return sketchPage(false);
 if(id==='tap-1'||id==='tap-2')return tapPage(id==='tap-1'?0:1);
 if(id==='try-home')return `${info('Tap your planned controls. The preview shows your chosen responses; you will program them in MIT later.','点击计划中的控件。预览会显示你写的回应；之后才在 MIT 中编程。')}<div class="own-demo-stage">${ownPreview(true)}<div class="card"><div class="eyebrow">${tr('Your idea is ready to start','你的创意已准备好开始')}</div><h2>${esc(state.design.title)}</h2>${state.design.pairs.map(p=>`<div class="tap-plan"><b>${esc(p.action)}</b><span>↓</span><p>${esc(p.response)}</p></div>`).join('')}<p class="small">${tr('Next: open MIT and create a project for THIS app. Your sketch stays here.','下一步：打开 MIT，为这个应用创建项目。草图会保留在这里。')}</p></div></div>`;
 if(id.startsWith('setup-'))return setupPage(Number(id.slice(-1)));
 if(id==='challenge-choice')return `${info('If you have time left, keep creating. Choose one challenge for the SAME app.','如果还有时间，继续创作。为同一个应用选择一个挑战。')}<div class="method-grid">${[['mit','▣','Make a first screen in MIT','在 MIT 中制作第一个界面','Use your sketch: add a title, a picture or placeholder, and two labelled buttons.','参考草图：添加标题、图片或占位图、两个带标签的按钮。'],['screen','✎','Design a second screen','设计第二个界面','Draw the page that opens after one homepage tap. Include a way back home.','画出主页某次点击后打开的页面，并加上返回主页的方法。']].map(([v,icon,en,zh,t,z])=>`<button class="method-card ${state.challenge.choice===v?'chosen':''}" data-challenge="${v}"><span class="method-icon">${icon}</span><h2>${tr(en,zh)}</h2><p>${tr(t,z)}</p><b>${state.challenge.choice===v?tr('Chosen ✓','已选择 ✓'):tr('Choose this','选择这个')} →</b></button>`).join('')}</div>`;
 if(id==='challenge-work')return challengePage();
 if(id.startsWith('pit-')&&id!=='pit-summary')return pitPage(id.slice(-1));
 if(id==='pit-summary')return pitSummary();
 if(id==='showcase')return `${info('You have designed the start of your OWN app. Here is what you are taking into the practical lesson.','你已经设计了自己应用的起点。这些内容会带到下一次实践课。')}<div class="own-demo-stage">${ownPreview(true)}<div><h2>${esc(state.design.title)||tr('Your app idea','你的应用创意')}</h2><p><b>${tr('For','目标用户')}:</b> ${esc(state.design.audience)}</p><p><b>${tr('It lets people','它让用户可以')}:</b> ${esc(state.design.feature)}</p>${completion()}<p class="note">${tr('Keep this first design. It is your starting point for the practical lesson.','保留第一版设计。它将是实践课的起点。')}</p></div></div>`;
 if(id==='finish-save')return finish();
 return '';
}
function quiz(n){const q=D.quiz[n],v=state.answers[n],checked=state.quizChecked[n];return `${info('Use the example and choose one answer. Then check the short feedback.','参考例子，选择一个答案，再看简短反馈。')}<div class="quiz-visual">${n===0?`<img src="assets/playground/gaming-phone.svg" alt="A gaming catalogue interface">`:`<div class="tap-strip"><span>${n===1?'▶':'▧'}</span><strong>${n===1?tr('Tap Play → a song starts','点击播放 → 歌曲开始'):tr('Tap artwork → its description appears','点击作品 → 作品介绍出现')}</strong></div>`}</div><fieldset><legend>${pair(q.q)}</legend>${q.options.map((o,i)=>`<label class="option ${checked&&q.answer===i?'correct':''}"><input type="radio" name="quiz" data-bind="answers.${n}" value="${i}" ${v===i?'checked':''}>${pair(o)}</label>`).join('')}</fieldset>${btn('Check this answer','检查答案','check-quiz','primary',`data-value="${n}"`)}${checked?`<div class="feedback"><b>${v===q.answer?tr('You spotted it','你发现了'):tr('Here’s the idea','看看这个概念')}</b><p>${pair(q.feedback)}</p></div>`:''}`;}
function focusSummary(){const f=C.learningFocus(state),labels=f.winners.map(k=>D.areas[k][state.lang==='bi'?1:0]);return `<div class="focus-summary"><div class="count-strip">${['K','S','U'].map(k=>`<span><b>${f.counts[k]||0}</b> ${pair(D.areas[k])}</span>`).join('')}</div><p>${f.max?tr(f.winners.length===1?D.areas[f.winners[0]][0]+' is your main practice focus today.':'You have a shared focus across '+f.winners.map(k=>D.areas[k][0]).join(' and ')+'.',f.winners.length===1?labels[0]+'是今天主要的练习重点。':'你的练习重点分布在'+labels.join('和')+'。'):tr('Keep what you already know. Untried checks are separate from things you need to practise.','保留已经掌握的内容。尚未尝试与需要练习的项目分开记录。')}</p></div>`;}
function learning(key){const k=key[0];return `${info('What is already secure, and what would you like to practise? An untried skill can stay “Not tried yet”.','哪些已经掌握，哪些想练习？还没试过的技能可以选择“尚未尝试”。')}<div class="area-banner"><b>${k}</b><div><h2>${pair(D.areas[k])}</h2><p>${pair(D.goals[k])}</p></div></div>${C.checks.filter(c=>c.id===key.toLowerCase()).map(c=>`<fieldset class="learning-check"><legend>${tr(c.en,c.zh)}</legend><div class="three choices">${[['secure','Already secure','已经掌握'],['focus','Practise today','今天练习'],['untried','Not tried yet','尚未尝试']].map(([v,en,zh])=>`<label class="option"><input type="radio" name="${c.id}" data-bind="learning.${c.id}" value="${v}" ${state.learning[c.id]===v?'checked':''}>${tr(en,zh)}</label>`).join('')}</div></fieldset>`).join('')}${key==='U2'?focusSummary():''}`;}
function boardData(){return state.slide==='challenge-work'&&state.challenge.choice==='screen'?state.challenge:state.design;}
function nodeHTML(n,preview=false){return `<button type="button" class="sketch-item type-${n.type} ${selected===n.id&&!preview?'selected':''}" ${preview?`data-own-tap="${n.id}"`:`data-node="${n.id}"`} style="left:${n.x}%;top:${n.y}%;width:${n.width||82}%" aria-label="${esc(n.label||n.type)}">${n.type==='image'?(n.image?`<img src="${n.image}" alt="My picture">`:n.art?art(n.art):'<span class="picture-placeholder">▧</span>'):''}<span>${esc(n.label)}</span></button>`;}
function inspector(){const n=boardData().nodes.find(n=>n.id===selected);return n?`<div class="inspector"><strong>${tr('Selected element','已选择元素')}</strong><label class="field">${tr('Its label / words','标签 / 文字')}<input data-node-label="${n.id}" value="${esc(n.label)}" maxlength="120"></label><div class="size-picks">${[['82','Full','整行'],['39','Half','半行'],['25','Small','小块']].map(([v,en,zh])=>`<button data-node-width="${v}">${tr(en,zh)}</button>`).join('')}</div>${n.type==='image'?`<div class="art-picks">${D.demos.map(d=>`<button data-node-art="${d.id}" title="${esc(d.kind[0])}">${art(d.id)}</button>`).join('')}</div><label class="btn quiet small">${tr('Use my own picture','使用自己的图片')}<input type="file" id="node-picture" accept="image/png,image/jpeg,image/webp" hidden></label>`:''}<p class="small">${tr('Drag to move. Or focus the element and use arrow keys.','拖动以移动，或选中元素后按方向键。')}</p>${btn('Delete this element','删除这个元素','delete-node','quiet small')}</div>`:`<div class="inspector"><strong>${tr('Choose an element','选择一个元素')}</strong><p>${tr('Select an element on the phone to change its words or picture.','选择手机上的元素，修改文字或图片。')}</p></div>`;}
function sketchPage(second){const d=second?state.challenge:state.design;return `${info(second?'Draw what opens after one homepage tap. Add a Back or Home control.':'Make a homepage with your name or logo, content, and two labelled things to tap. Use your own layout.',second?'画出主页某次点击后打开的页面，并加入返回或主页控件。':'设计有名称或标志、内容、两个带标签的点击项目的主页。布局由你决定。')}${state.design.method==='paper'?`<section class="paper-work"><div class="paper-icon">✎</div><h2>${tr(second?'Your second paper screen':'Your paper homepage',second?'你的第二个纸上界面':'你的纸上主页')}</h2><p>${tr('Collect paper from the front, or ask your teacher. Draw a phone outline, then put YOUR app design inside it.','到教室前方拿纸，或向老师索取。画出手机轮廓，再在里面设计你自己的应用。')}</p><label class="check"><input type="checkbox" data-bind="${second?'challenge':'design'}.paper" ${d.paper?'checked':''}>${tr('I have drawn and labelled my screen.','我已画好界面并添加标签。')}</label><label class="btn quiet">${tr('Add a photo to my report','给报告添加照片')}<input type="file" id="sketch-photo" accept="image/png,image/jpeg,image/webp" hidden></label>${d.photo?`<img class="photo-preview" src="${d.photo}" alt="Your paper sketch">${btn('Remove photo','移除照片','remove-photo','quiet small')}`:''}<p class="small">${tr('A photo is helpful but not required. Keep your paper with your PDF if no photo is added.','可以添加照片，但不强制。没有照片时，把纸上作品和 PDF 一起保留。')}</p></section>`:`<div class="builder-toolbar">${[['text','Text','文字'],['image','Picture','图片'],['button','Button','按钮'],['menu','Menu','菜单'],['input','Input','输入框']].map(([v,en,zh])=>btn('+ '+en,zh,'add-node','small',`data-value="${v}"`)).join('')}${btn('Undo','撤销','undo','small',undo.length?'':'disabled')}</div><div class="sketch-editor"><div class="phone-frame theme-${state.design.theme}"><div class="canvas-brand">${esc(state.design.logo)}</div><div class="board" id="sketch-board" aria-label="Your editable homepage">${d.nodes.map(n=>nodeHTML(n)).join('')}${d.nodes.length?'':`<div class="board-empty"><span>${esc(state.design.logo)}</span><p>${tr('Add Text for your app name. Then add a picture and two buttons.','添加文字写上应用名称，再加图片和两个按钮。')}</p>${btn('Add my app title','添加应用标题','add-title','small')}</div>`}</div></div><div id="inspector">${inspector()}</div></div><p class="small muted">${tr('This is a movable design sketch. Plan what two controls will do on the next two slides.','这是可以移动的设计草图。接下来两页会计划两个控件的功能。')}</p>`}`;}
function ownPreview(tappable=false,highlight=''){const d=state.design;if(d.method==='paper')return `<div class="paper-preview">${d.photo?`<img src="${d.photo}" alt="Your paper homepage">`:`<div class="paper-icon">✎</div><h3>${tr('Keep your paper beside you','把纸上作品放在身边')}</h3><p>${tr('Point to one labelled button on your drawing.','指向你画的一个带标签按钮。')}</p>`}</div>`;return `<div class="phone-frame preview-phone theme-${d.theme}"><div class="canvas-brand">${esc(d.logo)}</div><div class="board preview-board">${d.nodes.map(n=>tappable?nodeHTML(n,true):nodeHTML(n,true).replace('data-own-tap=','data-preview-select=')).join('')||`<div class="board-empty">${tr('Your sketch will appear here','你的草图会显示在这里')}</div>`}</div></div>`;}
function tapPage(i){const p=state.design.pairs[i],nodes=state.design.nodes.filter(n=>['button','menu','image','input'].includes(n.type));return `${info(i?'Choose a DIFFERENT control on the same homepage. What will this second tap do?':'Choose one control from YOUR homepage. What should happen when someone taps it?',i?'在同一个主页选择另一个控件。第二次点击会做什么？':'选择你自己主页上的一个控件。用户点击后应发生什么？')}<div class="tap-editor">${ownPreview(false,p.node)}<div class="tap-card"><span class="tap-number">${i+1}</span>${state.design.method==='digital'&&nodes.length?`<label class="field">${tr('When I tap…','当我点击……')}<select data-control="${i}"><option value="">${tr('Choose a control from my sketch','选择草图中的控件')}</option>${nodes.map(n=>`<option value="${n.id}" ${p.node===n.id?'selected':''}>${esc(n.label||n.type)}</option>`).join('')}</select></label>`:field('When I tap this labelled item…','当我点击这个带标签的项目……',`design.pairs.${i}.action`,tr('Copy the words from one button on your paper.','抄下纸上某个按钮的文字。'))}<span class="response-arrow">↓</span><p><b>${tr('The app will…','应用就会……')}</b></p><div class="effect-pills">${D.effects.map(t=>`<button data-effect="${t[0]}" data-pair="${i}" class="${p.effect===t[0]?'chosen':''}">${tr(t[1],t[2])}</button>`).join('')}</div>${field('What appears or starts?','出现什么，或开始什么？',`design.pairs.${i}.response`,tr('A few words. For example: “Show my character gallery” or “Start a 5-minute timer”.','几个词即可。例如：“显示我的角色画廊”或“开始五分钟计时”。'))}${state.guided?`<div class="note">${tr('Think: what would YOU expect after tapping those words? Name the page, information or action.','想一想：点了这些文字后，你希望发生什么？写出页面、资料或操作。')}</div>`:''}</div></div>`;}
function setupPage(n){const a=D.access[n];return `${info(n===0?'Your sketch is ready. Now open MIT to start a project for the SAME app. Keep this lesson open in its tab.':n===4?'Use your own app’s name. This starts the project you will build from your sketch.':'Follow this one setup step, then return here for the next slide.',n===0?'草图准备好了。现在打开 MIT，为同一个应用开始项目。保留本课标签页。':n===4?'使用自己应用的名称。这是之后按草图制作的项目。':'完成这一个设置步骤，再回到这里看下一页。')}${n===0?`<div class="route-choice">${[['new','New MIT account','新 MIT 账户'],['existing','I already have MIT access','我已有 MIT 账户']].map(([v,en,zh])=>`<label class="option"><input type="radio" name="mit-route" data-bind="setup.route" value="${v}" ${state.setup.route===v?'checked':''}>${tr(en,zh)}</label>`).join('')}</div>`:''}${n===4?`<div class="project-chip">${tr('My project name suggestion','项目名称建议')}: <code>${esc(projectSlug())}</code></div>`:''}<div class="setup-layout"><figure class="screenshot"><img src="assets/screens/${a.screen}" alt="${esc(a.title[0])}: genuine MIT screenshot"><button data-image="assets/screens/${a.screen}">${tr('Enlarge screenshot','放大截图')} ↗</button></figure><div><ol class="steps">${a.steps.map(t=>`<li>${pair(t)}</li>`).join('')}</ol><div class="note">${pair(a.note)}</div><div class="row"><a class="btn primary" target="_blank" rel="noopener" href="https://login.appinventor.mit.edu/login/">${tr(n===0?'Open MIT':'Return to MIT',n===0?'打开 MIT':'回到 MIT')} ↗</a>${n===1?`<a class="btn quiet" target="_blank" rel="noopener" href="https://outlook.office.com/mail/">${tr('School Outlook','学校 Outlook')} ↗</a>`:''}</div>${n===5?`<div class="status-options">${[['ready','My project is ready','我的项目准备好了'],['help','I need setup help','我需要设置帮助'],['waiting','Still waiting for email','还在等待邮件']].map(([v,en,zh])=>`<label class="option"><input type="radio" name="access-status" data-bind="setup.status" value="${v}" ${state.setup.status===v?'checked':''}>${tr(en,zh)}</label>`).join('')}</div>`:''}${[0,1,2].includes(n)?btn('I’m waiting / need access help','我在等待 / 需要账户帮助','access-help','quiet small'):''}</div></div>`;}
function projectSlug(){return state.design.title.replace(/[^a-zA-Z0-9_]/g,'').replace(/^[0-9]+/,'').slice(0,40)||'MyAppDesign';}
function challengePage(){if(state.challenge.choice==='screen')return sketchPage(true);return `${info('Use YOUR sketch beside MIT. Try putting the first pieces on Screen1. This is a visual start; no Blocks are required yet.','把你自己的草图放在 MIT 旁边。试着在 Screen1 放入初始组件。现在只做外观，不要求 Blocks。')}<div class="mit-build"><img src="assets/guides/R2-designer-orientation.png" alt="Genuine MIT Designer with labelled areas"><ol class="steps"><li>${tr('Designer: add a Label. Set its Text to your own app’s name.','在 Designer 添加 Label，把 Text 改成自己的应用名称。')}</li><li>${tr('Add an Image or use a Label as a picture placeholder.','添加 Image，或先用 Label 表示图片的位置。')}</li><li>${tr('Add two Buttons. Set their Text to the labels from your sketch.','添加两个 Button，把 Text 改成草图上的按钮标签。')}</li><li>${tr('Use Projects > Save project. Buttons do not have programmed actions yet.','使用 Projects > Save project 保存。按钮现在还没有编程功能。')}</li></ol></div><div class="row"><a class="btn primary" href="https://login.appinventor.mit.edu/login/" target="_blank" rel="noopener">${tr('Open MIT','打开 MIT')} ↗</a><button class="btn quiet" data-reference="R4-save-and-reopen.png">${tr('Save / reopen guide','保存 / 重新打开指南')}</button></div><label class="check"><input data-bind="challenge.paper" type="checkbox" ${state.challenge.paper?'checked':''}>${tr('I have saved my starting MIT screen.','我已保存起始 MIT 界面。')}</label>`;}
function pitPage(k){return `${info('Choose the confidence phase that fits THIS part of your learning. It can differ from your other areas.','选择符合这一部分学习的信心状态。不同领域可以不一样。')}<div class="area-banner"><b>${k}</b><div><h2>${pair(D.areas[k])}</h2><p>${pair(D.goals[k])}</p></div></div><div class="phase-grid">${Object.entries(D.phases).map(([v,t])=>`<label class="phase"><input type="radio" data-bind="pitstop.${k}" name="phase" value="${v}" ${state.pitstop[k]===v?'checked':''}><span><strong>${tr(t[0],t[1])}</strong><small>${tr(t[2],t[3])}</small></span></label>`).join('')}</div>`;}
function pitSummary(){const f=C.dominance(Object.values(state.pitstop));return `${info('This is your confidence across knowledge, skills and understanding. There is no written explanation to complete.','这是你在知识、技能和理解三个方面的信心状态，不需要再写解释。')}<div class="phase-summary">${['K','S','U'].map(k=>`<article><span>${k}</span><strong>${state.pitstop[k]?tr(D.phases[state.pitstop[k]][0],D.phases[state.pitstop[k]][1]):tr('Not selected','未选择')}</strong></article>`).join('')}</div><div class="focus-summary"><h2>${f.winners.length===1?tr('Your most selected phase','选择最多的状态'):tr('Your phases are shared','你有不同的学习状态')}</h2><p>${f.max?tr(f.winners.length===1?D.phases[f.winners[0]][0]+' was selected for '+f.max+' of '+f.total+' areas.':'There is a tie. Your areas do not all need to be in the same phase.',f.winners.length===1?'你在 '+f.total+' 个领域中，有 '+f.max+' 个选择了“'+D.phases[f.winners[0]][1]+'”。':'选择次数相同。各领域不必处于同一状态。'):tr('Choose a phase on the previous slides.','请在前面的页面选择状态。')}</p></div>`;}
function completion(){const labels={idea:['My own app idea','自己的应用创意'],sketch:['My homepage sketch','主页草图'],taps:['Two planned taps','两个点击计划']};return `<div class="completion">${Object.entries(C.completeness(state)).map(([k,v])=>`<div class="${v?'met':''}"><b>${v?'✓':'○'}</b>${pair(labels[k])}${!v?btn('Return to this part','返回这一部分','return-work','quiet small',`data-value="${k}"`):''}</div>`).join('')}</div>`;}
function finish(){return `${info('Save your design as a PDF, then upload it in Teams where your teacher directs you.','把设计保存成 PDF，然后按老师要求上传到 Teams。')}<section class="save-card"><span class="save-icon">↓</span><h2>${tr('Your app design, ready to keep','保留你的应用设计')}</h2><p>${tr('The report includes your idea, homepage, planned taps and learning reflection.','报告包含创意、主页、点击计划和学习反思。')}</p><div class="row">${btn('Save my PDF','保存 PDF','pdf','primary')}${btn('Preview report','预览报告','report','quiet')}</div><ol class="steps"><li>${tr('In the print window, select Save as PDF. On iPad, use print preview / Share to save to Files.','在打印窗口选择“另存为 PDF”。iPad 可通过打印预览 / 共享保存到“文件”。')}</li><li>${tr('Open the PDF and check the pages. Keep your paper sketch with it if you did not add a photo.','打开 PDF 检查页面。如果没有添加纸上草图的照片，请把纸上作品一起保留。')}</li><li>${tr('Upload the PDF in Teams. This website does not upload it for you.','在 Teams 上传 PDF。本网站不会替你上传。')}</li></ol></section><details><summary>${tr('Other copies / restore my work','其他副本 / 恢复作品')}</summary><p class="small">${tr('Backup: editable answers for this lesson. Readable report: a browser copy. Your main submission is the PDF.','备份用于恢复可编辑答案；可读报告是浏览器副本。主要提交文件为 PDF。')}</p><div class="row">${btn('Download backup','下载备份','backup','quiet')}${btn('Readable report','可读报告','html-report','quiet')}<label class="btn quiet">${tr('Restore backup','恢复备份')}<input id="restore-file" type="file" accept=".json,application/json" hidden></label></div></details>`;}
function teacherNotes(){return `<details class="teacher"><summary>Teacher notes · current slide and pacing</summary><p>The core outcome is one original homepage plus two planned tap responses. Exactly two Main Tasks. No improvement paragraph, real booking, live weather or finished code is required. Gallery examples are original fictional mock-ups, not MIT screenshots.</p><p>Students move forward through one slide at a time. Previous slides remain available. Teacher preview unlocks navigation. Account problems can take the explicit help route after the design stage; computing progress is not blocked by email.</p><table>${C.stages.map(g=>`<tr><td>${esc(g[1])}</td><td>${g[3]} min</td></tr>`).join('')}</table><p>Accept short phrases, Mandarin and paper designs. Two tap targets may be buttons, pictures or menu items. Designer makes appearance; Blocks makes behaviour. Preview responses are simulations of the student's intentions.</p><p>Research adapted, not copied: ${D.research.map(r=>`<a href="${r[1]}" target="_blank" rel="noopener">${esc(r[0])}</a>`).join(' · ')}</p></details>`;}
function render(focus=false){stopSimTicker();$('#app').innerHTML=state.joined?shell():landing();if(motionRequested)document.querySelectorAll('[data-motion]').forEach(el=>el.classList.add('motion-on'));motionRequested=false;refreshSimTicker();if(focus)$('#slide-title')?.focus({preventScroll:true});}
function go(id,override=false){if(!C.pages.some(p=>p.id===id))return;if(!override&&!C.canVisit(state,id,teacher)){toast('Follow the next slide first.','请先完成下一页。');return;}if(id!==state.slide)stopSimTicker(true);state.slide=id;state.stage=current().group;if(!state.visited.includes(id))state.visited.push(id);selected=null;undo=[];noticeLine='';save();history.replaceState(null,'','#'+id);render(true);window.scrollTo({top:0,behavior:'auto'});}
function validation(){const id=state.slide,d=state.design;
 if(['read-tap','play'].includes(id)&&![0,1].every(i=>state.demoTaps.includes(state.demo+'-'+i)))return ['Try both buttons on the example phone.','先试试示例手机上的两个按钮。'];
 if(id.startsWith('quiz-')&&!state.quizChecked[Number(id.slice(-1))])return ['Choose an answer and select Check this answer. A first attempt is enough to move on.','选择答案，再点击“检查答案”。尝试后即可继续。'];
 if(id.startsWith('learn-')&&C.checks.filter(c=>c.id===id.slice(6).toLowerCase()).some(c=>!state.learning[c.id]))return ['Choose a starting point for each check. You can select Not tried yet.','为每项选择起点。可以选择“尚未尝试”。'];
 if(id==='notice'&&!state.notice)return ['Try one button label to see its explanation.','选一个按钮标签，看看解释。'];
 const required={topic:['design.topic','Choose a topic or type your own.','选择主题，或写出自己的主题。'],name:['design.title','Give your app a name.','为应用起个名字。'],purpose:['design.feature','Choose or type one thing your app will do.','选择或写出应用要做的一件事。'],audience:['design.audience','Choose or name a group of people.','选择或写出一类用户。']};
 if(required[id]&&!String(get(required[id][0])).trim())return required[id].slice(1);
 if(id==='method'&&!d.method)return ['Choose paper or digital. Both are equally good.','选择纸上或数字草图。两种都可以。'];
 if(id==='sketch'&&d.method==='paper'&&!d.paper&&!d.photo)return ['Finish your paper screen, then tick the box. You can add a photo later.','画好纸上界面后勾选。照片可以之后添加。'];
 if(id==='sketch'&&d.method==='digital'&&(d.nodes.length<3||d.nodes.filter(n=>['button','image','menu','input'].includes(n.type)).length<2))return ['Add your title and at least two labelled tap targets. Pictures or buttons can be tap targets.','添加标题和至少两个带标签的点击项目。图片或按钮都可以。'];
 if(id==='tap-1'||id==='tap-2'){const i=id==='tap-1'?0:1,p=d.pairs[i];if(!p.action.trim()||!p.response.trim())return ['Choose the control and say what appears or starts. A short phrase is enough.','选择控件，再说明出现什么或开始什么。短语就够了。'];if(i&&p.action.trim().toLowerCase()===d.pairs[0].action.trim().toLowerCase())return ['Choose a different control for your second tap.','第二次点击请选择另一个控件。'];}
 if(id==='challenge-choice'&&!state.challenge.choice)return ['Choose one challenge. You can keep working on it only if time remains.','选择一个挑战。有剩余时间时继续做。'];
 if(id.startsWith('pit-')&&id!=='pit-summary'&&!state.pitstop[id.slice(-1)])return ['Choose the confidence phase that fits this area.','选择符合这一领域的信心状态。'];
 return null;
}
function next(){const v=validation();if(v){noticeLine=tr(v[0],v[1]);render();return;}const id=C.nextPage(state);state.maxUnlocked=Math.max(state.maxUnlocked,C.pages.findIndex(p=>p.id===id));go(id);}
function back(){let i=C.pages.findIndex(p=>p.id===state.slide)-1;while(state.setup.route==='existing'&&['setup-1','setup-2'].includes(C.pages[i]?.id))i--;go(C.pages[Math.max(0,i)].id);}
function modal(title,html){$('#resource-content').innerHTML=`<header class="dialog-head"><strong>${title}</strong>${btn('Close','关闭','close','quiet small')}</header><div class="dialog-body">${html}</div>`;$('#resource-dialog').showModal();}
function showGuides(){modal(tr('MIT guides for your design','为你的设计提供的 MIT 指南'),`<p>${tr('Create your sketch first. These references support the MIT stage afterwards.','先画自己的草图。这些参考用于之后的 MIT 阶段。')}</p><div class="resource-grid">${D.references.map(r=>`<button data-reference="${r[0]}">${tr(r[1],r[2])} ↗</button>`).join('')}</div><p class="small">${tr('The earlier activity worksheets are replaced by the new slides and playground examples.','之前的活动工作纸已由新版幻灯片和创意示例取代。')}</p>`);}
function remember(){undo.push(JSON.stringify(boardData().nodes));if(undo.length>20)undo.shift();const b=$('[data-act="undo"]');if(b)b.disabled=false;}
function addNode(type){const d=boardData();if(d.nodes.length>=30)return toast('Use or edit the elements you have.','请使用或修改已有元素。');remember();let count=d.nodes.length;const n={id:'n'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),type,art:type==='image'?'':'',width:82,label:{text:state.design.title||'My app',image:state.lang==='bi'?'我的图片':'My picture',button:state.lang==='bi'?'按钮名称':'Button label',menu:state.lang==='bi'?'我的选项':'My choices',input:state.lang==='bi'?'输入什么？':'Type here'}[type],x:9,y:type==='text'?5:type==='image'?20:Math.min(84,61+d.nodes.filter(x=>['button','menu','input'].includes(x.type)).length*15)};d.nodes.push(n);selected=n.id;save();render();cueNewElement();}
function clamp(n){n.x=Math.max(0,Math.min(100-(n.width||82),n.x));n.y=Math.max(0,Math.min(n.type==='image'?68:86,n.y));}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),15000);}
const filename=ext=>(state.student.name||'Year9').replace(/[^a-zA-Z0-9_-]+/g,'_')+'-App-Design.'+ext;
async function pictureData(d){if(state.design.method==='paper')return d.photo;if(!d.nodes?.length)return '';await document.fonts.ready;const cv=document.createElement('canvas');cv.width=720;cv.height=1200;const x=cv.getContext('2d'),colours={mint:['#edf5e7','#275c4c'],lilac:['#eeebff','#514bc5'],peach:['#fff0e5','#a2493b'],sky:['#e9f6fd','#236a8d'],night:['#283844','#f9e0a4']},cols=colours[state.design.theme];x.fillStyle=cols[0];x.fillRect(0,0,720,1200);x.fillStyle=cols[1];x.font='35px Raleway, sans-serif';x.fillText(state.design.logo,650,44);
 for(const n of d.nodes){const l=n.x*7.2,t=n.y*12,w=720*(n.width||82)/100,h=n.type==='image'?330:n.type==='text'?105:115;x.save();x.beginPath();x.rect(l,t,w,h);x.clip();x.fillStyle=n.type==='button'?cols[1]:'#ffffff';x.fillRect(l,t,w,h);x.strokeStyle='#a6b7aa';x.strokeRect(l,t,w,h);if(n.type==='image'&&(n.image||n.art)){const im=new Image();im.src=n.image||'assets/playground/'+n.art+'-art.svg';try{await im.decode();const fit=Math.min((w-20)/im.width,240/im.height),iw=im.width*fit,ih=im.height*fit;x.drawImage(im,l+(w-iw)/2,t+8,iw,ih);}catch{}}
 x.fillStyle=n.type==='button'?cols[0]:'#203c30';x.font=(n.type==='text'?'bold 34px':'29px')+' Raleway, sans-serif';let yy=t+(n.type==='image'&&(n.image||n.art)?275:43),line='';const tokens=Array.from(n.label);for(const c of tokens){if(x.measureText(line+c).width>w-32){x.fillText(line,l+16,yy);yy+=36;line=c;}else line+=c;}if(line)x.fillText(line,l+16,yy);x.restore();}
 return cv.toDataURL('image/png');}
async function openReport(print){save();const win=window.open('about:blank','_blank');if(!win)return toast('Allow the report window, then try again.','允许报告窗口，然后重试。');try{const imgs={main:await pictureData(state.design),second:state.challenge.choice==='screen'?await pictureData(state.challenge):''};const value=JSON.stringify(imgs);sessionStorage.setItem(C.KEY+'-images',value);win.sessionStorage.setItem(C.KEY+'-images',value);win.location.replace(location.pathname+'?report=1'+(print?'&print=1':''));}catch{win.close();toast('The report could not open. Download your backup and try again.','无法打开报告。先下载备份，再重试。');}}
async function action(act,el){
 if(act==='next')return next();if(act==='back')return back();if(act==='home'){stopSimTicker(true);state.joined=false;save();render();return;}
 if(act==='new'){if(!confirm('Start a new response? Save your PDF or backup first. / 开始新答卷？请先保存 PDF 或备份。'))return;stopSimTicker();simulation=Sim.initial();demoResult=null;lastDemoLabel=null;const lang=state.lang;state=C.initial();state.lang=lang;save();render();return;}
 if(act==='goals'){$('#layout').classList.toggle('goals-open');return;}
 if(act==='close'){$('#resource-dialog').close();return;}
 if(act==='identity')return modal(tr('My details and support','我的信息与支持'),`${field('Name','姓名','student.name')}${field('Class','班级','student.form')}<label class="check"><input type="checkbox" data-bind="guided" ${state.guided?'checked':''}>${tr('Extra prompts','更多提示')}</label>`);
 if(act==='glossary')return modal(tr('Words for app designers','应用设计词汇'),`<div class="glossary">${D.glossary.map(g=>`<article><h3>${tr(g[0],g[1])}</h3><p>${tr(g[2],g[3])}</p></article>`).join('')}</div>`);
 if(act==='guides')return showGuides();
 if(act==='save-menu')return modal(tr('Keep or restore my design','保存或恢复设计'),`<p>${tr('PDF keeps a readable copy. A backup restores your editable work.','PDF 保留可读副本。备份能恢复可编辑作品。')}</p><div class="row">${btn('Save PDF','保存 PDF','pdf','primary')}${btn('Download backup','下载备份','backup','quiet')}<label class="btn quiet">${tr('Restore backup','恢复备份')}<input id="restore-file" type="file" accept=".json,application/json" hidden></label></div>`);
 if(act==='check-quiz'){const n=Number(el.dataset.value);if(state.answers[n]===undefined)return toast('Choose one answer first.','请先选择答案。');state.quizChecked[n]=true;save();render();return;}
 if(act==='add-title')return addNode('text');if(act==='add-node')return addNode(el.dataset.value);
 if(act==='delete-node'){remember();const d=boardData();d.nodes=d.nodes.filter(n=>n.id!==selected);selected=null;save();render();return;}
 if(act==='undo'){if(undo.length)boardData().nodes=JSON.parse(undo.pop());selected=null;save();render();return;}
 if(act==='remove-photo'){boardData().photo='';save();render();return;}
 if(act==='access-help'){state.setup.status=state.slide==='setup-1'||state.slide==='setup-2'?'waiting':'help';const id='challenge-choice';state.maxUnlocked=Math.max(state.maxUnlocked,C.pages.findIndex(p=>p.id===id));go(id);toast('Your design is saved. You can draw a second screen while waiting.','设计已保存。等待时可以画第二个界面。');return;}
 if(act==='return-work'){const id={idea:'name',sketch:'sketch',taps:'tap-1'}[el.dataset.value];return go(id);}
 if(act==='pdf'||act==='report')return openReport(act==='pdf');
 if(act==='backup'){download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),filename('json'));return;}
 if(act==='html-report'){const images={main:await pictureData(state.design),second:state.challenge.choice==='screen'?await pictureData(state.challenge):''};download(new Blob([window.LessonReport.html(state,images)],{type:'text/html;charset=utf-8'}),filename('html'));return;}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-act],[data-jump],[data-demo],[data-demo-tap],[data-sim-action],[data-notice],[data-topic],[data-phrase],[data-logo],[data-theme],[data-method],[data-node-art],[data-node-width],[data-own-tap],[data-preview-select],[data-effect],[data-challenge],[data-image],[data-reference]');if(!el)return;
 if(el.dataset.act)return void action(el.dataset.act,el);if(el.dataset.jump)return go(el.dataset.jump);
 if(el.dataset.demo){stopSimTicker(true);state.demo=el.dataset.demo;demoResult=null;lastDemoLabel=null;lastSimAction='';save();render();return;}
 if(el.dataset.demoTap!==undefined){const index=Number(el.dataset.demoTap),d=D.demos.find(d=>d.id===state.demo);lastSimAction='';lastDemoLabel=demoButtonText(d,index);if(!(state.demo==='planner'&&index===0))stopSimTicker(true);demoResult=index;Sim.tap(simulation,state.demo,index);motionRequested=true;const key=state.demo+'-'+index;if(!state.demoTaps.includes(key))state.demoTaps.push(key);save();render();document.querySelector('[data-demo-tap="'+index+'"]').focus({preventScroll:true});return;}
 if(el.dataset.simAction){const act=el.dataset.simAction,val=el.dataset.simValue;if(act==='reset'){lastDemoLabel=['Reset sample timer','重置示例计时器'];Sim.timerAction(simulation,'reset');}else {Sim.choose(simulation,act,val);lastDemoLabel=[val,val];lastSimAction=act;}motionRequested=true;render();const control=[...document.querySelectorAll('[data-sim-action]')].find(x=>x.dataset.simAction===act&&x.dataset.simValue===val);control?.focus({preventScroll:true});return;}
 if(el.dataset.notice){state.notice=el.dataset.notice;save();render();return;}
 if(el.dataset.topic!==undefined){const i=Number(el.dataset.topic);state.design.topic=i===D.topics.length-1?'':D.topics[i][state.lang==='bi'?1:0];save();render();$('input[data-bind="design.topic"]')?.focus();return;}
 if(el.dataset.phrase){set(el.dataset.target,el.dataset.phrase);save();render();return;}
 for(const [data,key] of [['logo','logo'],['theme','theme'],['method','method']])if(el.dataset[data]){state.design[key]=el.dataset[data];save();render();return;}
 if(el.dataset.nodeWidth){const n=boardData().nodes.find(n=>n.id===selected);if(n){remember();n.width=Number(el.dataset.nodeWidth);clamp(n);save();render();}return;}
 if(el.dataset.nodeArt){const n=boardData().nodes.find(n=>n.id===selected);if(n){remember();n.art=el.dataset.nodeArt;n.image='';save();render();}return;}
 if(el.dataset.previewSelect){selected=el.dataset.previewSelect;return;}
 if(el.dataset.ownTap){const n=state.design.nodes.find(n=>n.id===el.dataset.ownTap),p=state.design.pairs.find(p=>p.node===el.dataset.ownTap||p.action===n?.label);if(p?.response)return modal(tr('Your planned response','你计划的回应'),`<div class="planned-response prototype-response motion-on" data-motion>${plannedCue(p.effect)}<h2>${esc(p.response)}</h2><p>${tr('A preview of your idea. You will program this behaviour in a later MIT lesson.','这是想法预览。之后会在 MIT 课程中为这个功能编程。')}</p></div>`);return toast('Choose a control you planned on the tap slides.','请选择在点击计划页设置过的控件。');}
 if(el.dataset.effect){const p=state.design.pairs[Number(el.dataset.pair)],ef=D.effects.find(t=>t[0]===el.dataset.effect);p.effect=ef[0];save();render();return;}
 if(el.dataset.challenge){state.challenge.choice=el.dataset.challenge;save();render();return;}
 if(el.dataset.image)return modal(tr('MIT screenshot','MIT 截图'),`<img src="${esc(el.dataset.image)}" alt="Genuine MIT screenshot">`);
 if(el.dataset.reference){const r=D.references.find(r=>r[0]===el.dataset.reference);return modal(tr(r[1],r[2]),`<p>${tr(r[3],r[4])}</p><img src="assets/guides/${r[0]}" alt="${esc(r[1])}">`);}
});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.nodeLabel){const n=boardData().nodes.find(n=>n.id===el.dataset.nodeLabel);if(n){n.label=el.value;if(boardData()===state.design)for(const p of state.design.pairs)if(p.node===n.id)p.action=n.label;const v=[...document.querySelectorAll('[data-node]')].find(x=>x.dataset.node===n.id);if(v){v.querySelector('span').textContent=n.label;v.setAttribute('aria-label',n.label);}save();}return;}if(el.dataset.bind&&!['radio','checkbox','file'].includes(el.type)){set(el.dataset.bind,el.value);save();if(el.dataset.bind==='design.title'&&$('#live-app-name'))$('#live-app-name').textContent=el.value;}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='language'){state.lang=el.value;save();render();return;}
 if(el.dataset.bind&&['radio','checkbox'].includes(el.type)){let v=el.type==='checkbox'?el.checked:el.value;if(el.dataset.bind.startsWith('answers.'))v=Number(v);set(el.dataset.bind,v);save();render();return;}
 if(el.dataset.control!==undefined){const p=state.design.pairs[Number(el.dataset.control)],n=state.design.nodes.find(n=>n.id===el.value);p.node=n?.id||'';p.action=n?.label||'';save();render();return;}
 if(el.id==='node-picture'&&el.files[0]){const file=el.files[0],data=boardData(),id=selected;if(!/^image\/(png|jpeg|webp)$/.test(file.type))return toast('Choose a PNG, JPEG or WebP picture.','请选择 PNG、JPEG 或 WebP 图片。');const u=URL.createObjectURL(file),im=new Image();im.onload=()=>{const cv=document.createElement('canvas'),sc=Math.min(1,700/Math.max(im.width,im.height));cv.width=Math.round(im.width*sc);cv.height=Math.round(im.height*sc);cv.getContext('2d').drawImage(im,0,0,cv.width,cv.height);const n=data.nodes.find(n=>n.id===id);if(n){remember();n.image=cv.toDataURL('image/jpeg',.72);n.art='';save();render();}URL.revokeObjectURL(u);};im.onerror=()=>URL.revokeObjectURL(u);im.src=u;return;}
 if(el.id==='sketch-photo'&&el.files[0]){const f=el.files[0];if(!/^image\/(png|jpeg|webp)$/.test(f.type))return toast('Choose a PNG, JPEG or WebP image.','请选择 PNG、JPEG 或 WebP 图片。');const url=URL.createObjectURL(f),im=new Image();im.onload=()=>{const cv=document.createElement('canvas'),sc=Math.min(1,1400/Math.max(im.width,im.height));cv.width=Math.round(im.width*sc);cv.height=Math.round(im.height*sc);cv.getContext('2d').drawImage(im,0,0,cv.width,cv.height);boardData().photo=cv.toDataURL('image/jpeg',.8);URL.revokeObjectURL(url);save();render();};im.onerror=()=>{URL.revokeObjectURL(url);toast('This image could not be read.','无法读取这张图片。');};im.src=url;return;}
 if(el.id==='restore-file'&&el.files[0]){try{if(el.files[0].size>7000000)throw Error('File too large');const restored=C.restore(JSON.parse(await el.files[0].text()));if(!confirm('Replace current work with this backup? / 用备份替换当前作品？'))return;state=restored;$('#resource-dialog').close();try{sessionStorage.removeItem(C.KEY+'-images');}catch{}save();history.replaceState(null,'','#'+state.slide);render();toast('Your work is restored.','作品已恢复。');}catch{toast('This is not a readable backup for this lesson.','这不是本课可读取的备份。');}}
});
document.addEventListener('submit',e=>{if(e.target.id!=='entry-form')return;e.preventDefault();if(!state.student.name.trim())return toast('Enter your name to label your work.','请输入姓名，以标识你的作品。');state.guided=$('#entry-guided').checked||C.guidedName(state.student.name);if(C.guidedName(state.student.name))state.lang='bi';state.joined=true;save();go(state.slide);});
document.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-node]'),board=$('#sketch-board');if(!el||!board)return;const n=boardData().nodes.find(n=>n.id===el.dataset.node);if(!n)return;selected=n.id;document.querySelectorAll('[data-node]').forEach(x=>x.classList.toggle('selected',x.dataset.node===selected));$('#inspector').innerHTML=inspector();drag={id:n.id,startX:e.clientX,startY:e.clientY,x:n.x,y:n.y,rect:board.getBoundingClientRect(),before:JSON.stringify(boardData().nodes)};board.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!drag)return;const n=boardData().nodes.find(n=>n.id===drag.id);if(!n)return;n.x=drag.x+(e.clientX-drag.startX)/drag.rect.width*100;n.y=drag.y+(e.clientY-drag.startY)/drag.rect.height*100;clamp(n);const el=[...document.querySelectorAll('[data-node]')].find(x=>x.dataset.node===n.id);el.style.left=n.x+'%';el.style.top=n.y+'%';});
function endDrag(){if(!drag)return;if(drag.before!==JSON.stringify(boardData().nodes)){undo.push(drag.before);if(undo.length>20)undo.shift();}drag=null;save();const el=$('[data-act="undo"]');if(el)el.disabled=!undo.length;}
document.addEventListener('pointerup',endDrag);document.addEventListener('pointercancel',endDrag);
document.addEventListener('focusin',e=>{if(e.target.dataset.nodeLabel){remember();return;}if(e.target.dataset.node){selected=e.target.dataset.node;document.querySelectorAll('[data-node]').forEach(x=>x.classList.toggle('selected',x.dataset.node===selected));if($('#inspector'))$('#inspector').innerHTML=inspector();}});
document.addEventListener('keydown',e=>{if(!e.target.dataset.node)return;const n=boardData().nodes.find(n=>n.id===e.target.dataset.node);if(!n)return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();remember();const d=e.shiftKey?5:1;n.x+=e.key==='ArrowLeft'?-d:e.key==='ArrowRight'?d:0;n.y+=e.key==='ArrowUp'?-d:e.key==='ArrowDown'?d:0;clamp(n);e.target.style.left=n.x+'%';e.target.style.top=n.y+'%';save();}if(e.key==='Delete'){e.preventDefault();action('delete-node',e.target);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopSimTicker(true);updateTimerUI();}});
window.addEventListener('pagehide',()=>stopSimTicker(true));
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(C.pages.some(p=>p.id===id)){if(C.canVisit(state,id,teacher))go(id);else history.replaceState(null,'','#'+state.slide);}});
if(new URLSearchParams(location.search).get('report')==='1'){let images={};try{images=JSON.parse(sessionStorage.getItem(C.KEY+'-images')||'{}');}catch{}window.LessonReport.show(state,images,new URLSearchParams(location.search).get('print')==='1');}else{const id=location.hash.slice(1);if(state.joined&&C.pages.some(p=>p.id===id)&&C.canVisit(state,id,teacher))state.slide=id;if(state.joined)history.replaceState(null,'','#'+state.slide);render();}
})();
